```cpp[]
class Solution {
   public:
    vector<int> search(string text, string pattern) {

        string st = pattern + '#' + text;

        int n = st.size();
        int m = pattern.size();

        vector<int> z(n, 0);

        int left = 0, right = 0;

        for (int i = 1; i < n; ++i) {
            int match = 0;

            if (i <= right) z[i] = min(z[i - left], right - i + 1);

            while (i + match < n && st[match] == st[i + match])
                ++match;

            z[i] = match;

            if (i + match - 1 > right) {
                left = i;
                right = i + match;
            }
        }

        vector<int> ans;

        for (int i = m + 1; i < n; i++) {

            if (z[i] >= m) {
                ans.push_back(i - (m + 1));
            }
        }

        return ans;
    }
};
```

